package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class LocaleUtils_toLocale_TriageGen1Test {

    @Test
    public void testToLocale_Null() {
        assertNull(LocaleUtils.toLocale(null));
    }

    @Test
    public void testToLocale_TooShort() {
        try {
            LocaleUtils.toLocale("a");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: a", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidLowercase() {
        // First char not lowercase
        try {
            LocaleUtils.toLocale("En");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: En", e.getMessage());
        }

        // Second char not lowercase
        try {
            LocaleUtils.toLocale("eN");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: eN", e.getMessage());
        }
    }

    @Test
    public void testToLocale_ValidLanguageOnly() {
        Locale result = LocaleUtils.toLocale("en");
        assertEquals(new Locale("en"), result);
    }

    @Test
    public void testToLocale_InvalidLengthMid() {
        // len is 3 or 4 and not 2
        try {
            LocaleUtils.toLocale("en_");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_", e.getMessage());
        }

        try {
            LocaleUtils.toLocale("en_a");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_a", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidSeparator() {
        try {
            LocaleUtils.toLocale("en-US");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en-US", e.getMessage());
        }
    }

    @Test
    public void testToLocale_LanguageAndVariant_WithDoubleUnderscore() {
        // Logic: if (ch3 == '_') return new Locale(str.substring(0, 2), "", str.substring(4));
        // Input: "en__US" -> ch0='e', ch1='n', ch2='_', ch3='_', ch4='U'
        // Note: The code checks ch3 == '_' BEFORE checking if ch3/ch4 are uppercase.
        Locale result = LocaleUtils.toLocale("en__US");
        assertEquals(new Locale("en", "", "US"), result);
    }

    @Test
    public void testToLocale_InvalidCountryCase() {
        // ch3 or ch4 not uppercase
        try {
            LocaleUtils.toLocale("en_us");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_us", e.getMessage());
        }

        try {
            LocaleUtils.toLocale("en_uS");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_uS", e.getMessage());
        }
    }

    @Test
    public void testToLocale_LanguageAndCountry() {
        Locale result = LocaleUtils.toLocale("en_US");
        assertEquals(new Locale("en", "US"), result);
    }

    @Test
    public void testToLocale_TooShortForCountry() {
        // len is 5, but we need to check if it hits the len < 7 block for the next part
        // The code handles len == 5 specifically.
        // Let's test len = 6 which should fail the len < 7 check if it passes the len == 5 check.
        try {
            LocaleUtils.toLocale("en_US_"); 
            // len=6. ch0-1=en, ch2=_, ch3=U, ch4=S, ch5=_
            // This actually satisfies the logic for len < 7 check if it reaches there.
            // Wait, if len is 6, it skips len == 5, checks len < 7, and throws.
            LocaleUtils.toLocale("en_US_");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_US_", e.getMessage());
        }
    }

    @Test
    public void testToLocale_LanguageCountryVariant() {
        // len = 8: "en_US_v" -> 01 2 34 5 67
        // "en_US_x" -> len 7. 
        // Let's try "en_US_1" (len 7)
        Locale result = LocaleUtils.toLocale("en_US_1");
        assertEquals(new Locale("en", "US", "1"), result);

        // Test length 7 exactly
        Locale result2 = LocaleUtils.toLocale("en_US_A");
        assertEquals(new Locale("en", "US", "A"), result2);
    }

    @Test
    public void testToLocale_InvalidSeparatorThirdPart() {
        // len 7, but ch5 is not '_'
        try {
            LocaleUtils.toLocale("en_US-1");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_US-1", e.getMessage());
        }
    }
}
